#[cfg(test)]
mod tests {
    use super::RULES;

    #[test]
    fn rule_ids_are_unique_and_well_formed() {
        let mut seen = std::collections::HashSet::new();
        for (id, site) in RULES {
            assert!(seen.insert(*id), "duplicate rule id {id}");
            let ok = id.starts_with("G")
                || id.starts_with("S")
                || (id.starts_with('M') && id.contains('-'));
            assert!(ok, "unexpected rule id {id}");
            assert!(!site.is_empty(), "{id} has no implementation site");
        }
    }
}
